<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Client\Application\Usecase\DeleteDynamicClient;

use Civi\Lughauth\Features\Oidc\Client\Domain\Gateway\DynamicClientGateway;
use Civi\Lughauth\Features\Oidc\Client\Domain\Exception\DynamicClientException;

final class DeleteDynamicClientUsecase
{
    public function __construct(
        private readonly DynamicClientGateway $gateway,
    ) {
    }

    public function delete(string $clientId, string $registrationAccessToken): void
    {
        $deleted = $this->gateway->delete($clientId, $registrationAccessToken);
        if (!$deleted) {
            throw DynamicClientException::invalidToken();
        }
    }
}
